"""Read-only linked-worktree upstream publication / no-replay oracle."""
from pathlib import Path
import json,hashlib,stat,sqlite3,subprocess,sys
out=Path(__file__).resolve().parent;f=json.loads((out/'fixture.json').read_text());root=Path(f['workspace_root'])
def snapshot(directory):return {str(p.relative_to(directory)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':stat.S_IMODE(p.stat().st_mode)} for p in sorted(directory.rglob('*')) if p.is_file()}
before=json.loads((out/'baseline.json').read_text());actual=snapshot(root);assert set(before)==set(actual);changed=[p for p in actual if actual[p]!=before[p]];assert changed==['repository/.git/config'];config=Path(f['repository']+'/.git/config').read_bytes();suffix=b'\n[branch "main"]\n\tremote = "origin"\n\tmerge = "refs/heads/main"\n';assert config.endswith(suffix);assert hashlib.sha256(config[:-len(suffix)]).hexdigest()==before['repository/.git/config']['sha256'];assert actual['repository/.git/config']['mode']==before['repository/.git/config']['mode']
for directory in [f['repository'],f['linked_worktree']]:
 for key,value in [('branch.main.remote','origin'),('branch.main.merge','refs/heads/main')]:assert subprocess.check_output(['git','-C',directory,'config','--get',key],text=True).strip()==value
 assert subprocess.run(['git','-C',directory,'config','--get-regexp','^branch.g06-linked-upstream\.'],capture_output=True).returncode==1
assert snapshot(Path(f['server_root'])/'remotes')==json.loads((out/'remote-baseline.json').read_text())
requests=[json.loads(l) for l in Path(f['server_root']+'/requests.jsonl').read_text().splitlines()];assert requests==[{'method':'GET','path':'/grand.git/info/refs'}]
c=sqlite3.connect('file:'+f['state']+'/state.db?mode=ro',uri=True);assert c.execute('pragma integrity_check').fetchone()[0]=='ok';obs=[json.loads(v)['value'] for(v,)in c.execute("select value from state where key like 'remote-observation:%'")];upstream=[json.loads(v)['value'] for(v,)in c.execute("select value from state where key like 'upstream:%'")];assert obs==[json.loads((out/'observed.json').read_text())];assert upstream==[json.loads((out/'upstream-complete.json').read_text())];assert upstream[0]['phase']=='complete' and upstream[0]['configuration']=='updated';assert c.execute('select count(*) from write_operations').fetchone()[0]==0;assert c.execute('select worktree_id,revoked from write_trust').fetchall()==[(f['worktree'],1)];assert c.execute("select count(*) from state where key like 'fetch-capture:%' or key like 'fetch-import:%' or key like 'push-check:%'").fetchone()[0]==0
result={'only_shared_config_changed':True,'original_config_prefix_preserved':True,'exact_two_key_suffix_added':True,'both_checkouts_other_files_bytes_modes_preserved':True,'linked_branch_settings_untouched':True,'bare_remote_bytes_modes_preserved':True,'one_real_observation_get':True,'observation_and_upstream_records_unchanged':True,'upstream_complete_updated':True,'main_trust_revoked':True,'no_linked_trust_grant':True,'local_write_operation_rows':0,'other_remote_operation_rows':0,'sqlite_integrity':'ok'}
(out/('oracle-'+sys.argv[1]+'.json')).write_text(json.dumps(result,indent=2)+'\n');print(result)
